"""The seed registry.

Each seed is one defect drawn from a real defect class. A seed knows how to
look for the code shape it needs inside a parsed module and how to change
that shape. When the shape is absent the seed reports that it does not
apply, and the caller records not applicable for that target.

One call to a seed apply function plants at every match in the tree it is
given. The matches are collected from the tree as parsed, before any
change is made, and each matched node is planted exactly once, so a
planting never creates a new match for itself inside the same call and a
planted shape that would itself match is never planted a second time.

Transforms only ever run on scratch copies. Nothing in this module writes
to a file.
"""
import ast
from dataclasses import dataclass
from typing import Callable

def _sorted_nodes(tree):
    nodes = [node for node in ast(tree) if hasattr(node, 'lineno')]
    return sorted(nodes, key=lambda n: (n, n, type(n)))

def _is_zero_literal(node):
    """A numeric zero in any literal spelling, plus sign included."""
    if isinstance(node, ast) and isinstance(node, ast):
        node = node
    return isinstance(node, ast) and isinstance(node, (int, float, complex)) and (not isinstance(node, bool)) and (node == 0)

def _is_int_constant(node):
    return isinstance(node, ast) and isinstance(node, int) and (not isinstance(node, bool))

def _apply_stale_version(tree):
    targets = []
    for node in _sorted_nodes(tree):
        value = None
        if isinstance(node, ast) and isinstance(node, ast):
            if any((isinstance(target, ast) and target in ('VERSION', '__version__', 'version') for target in node)):
                value = node
        if isinstance(node, ast) and isinstance(node, ast):
            if isinstance(node, ast) and node in ('VERSION', '__version__', 'version'):
                value = node
        if value is not None and isinstance(value, str):
            targets(value)
    for value in targets:
        value = '9.9.9'
    return bool(targets)

def _apply_dropped_return(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and node is not None]
    for node in targets:
        node = None
    return bool(targets)
_COMPARISON_FLIPS = {ast: ast, ast: ast, ast: ast, ast: ast, ast: ast, ast: ast, ast: ast, ast: ast, ast: ast, ast: ast}

def _apply_inverted_comparison(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast) and node:
            flipped = _COMPARISON_FLIPS(type(node[0]))
            if flipped is not None:
                targets((node, flipped))
    for node, flipped in targets:
        node[0] = flipped()
    return bool(targets)

def _apply_off_by_one(tree):
    targets = []
    seen = set()
    for node in _sorted_nodes(tree):
        if isinstance(node, (ast, ast)):
            for inner in ast(node):
                if _is_int_constant(inner) and id(inner) not in seen:
                    seen(id(inner))
                    targets(inner)
    for target in targets:
        target = target + 1
    return bool(targets)

def _apply_swallowed_exception(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast):
            if len(node) == 1 and isinstance(node[0], ast):
                continue
            targets(node)
    for node in targets:
        node = [ast()]
    return bool(targets)

def _apply_inverted_boolean(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and isinstance(node, bool)]
    for node in targets:
        node = not node
    return bool(targets)
_ARITHMETIC_SWAPS = {ast: ast, ast: ast, ast: ast}

def _apply_swapped_arithmetic(tree):
    targets = [(node, _ARITHMETIC_SWAPS[type(node)]) for node in _sorted_nodes(tree) if isinstance(node, ast) and type(node) in _ARITHMETIC_SWAPS]
    for node, replacement in targets:
        node = replacement()
    return bool(targets)

def _apply_dropped_call_argument(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and len(node) >= 2]
    for node in targets:
        node = node[:-1]
    return bool(targets)

def _apply_negated_condition(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast)]
    for node in targets:
        node = ast(op=ast(), operand=node)
    return bool(targets)

def _apply_removed_element(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast) and node:
            targets(node)
        elif isinstance(node, ast) and node:
            targets(node)
    for node in targets:
        if isinstance(node, ast):
            node = node[1:]
            node = node[1:]
        else:
            node = node[1:]
    return bool(targets)

def _apply_range_bound_shift(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and isinstance(node, ast) and (node == 'range') and node]
    for node in targets:
        last = node[-1]
        node[-1] = ast(left=last, op=ast(), right=ast(value=1))
    return bool(targets)

def _own_returns(node):
    """The return statements that belong to one function body.

    The walk descends through the statements of the body and
    stops at any nested function or class, because a return
    inside one of those belongs to that nested scope and is
    judged against its own parameter list when the walk of the
    whole tree reaches it.
    """
    found = []
    stack = list(node)
    while stack:
        current = stack()
        if isinstance(current, (ast, ast, ast, ast)):
            continue
        if isinstance(current, ast):
            found(current)
        stack(ast(current))
    return found

def _apply_wrong_variable_returned(tree):
    targets = []
    planted = set()
    for node in _sorted_nodes(tree):
        if not isinstance(node, ast):
            continue
        params = [arg for arg in node]
        if len(params) < 2:
            continue
        for inner in _own_returns(node):
            if isinstance(inner, ast) and inner in params and (id(inner) not in planted):
                planted(id(inner))
                index = params(inner)
                targets((inner, params[(index + 1) % len(params)]))
    for inner, name in targets:
        inner = name
    return bool(targets)
_OPERAND_SWAP_OPS = (ast, ast, ast, ast)

def _apply_swapped_operand_order(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and isinstance(node, _OPERAND_SWAP_OPS)]
    for node in targets:
        node, node = (node, node)
    return bool(targets)

def _apply_dropped_else(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and node]
    for node in targets:
        node = []
    return bool(targets)

def _apply_swapped_boolean_operator(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast)]
    for node in targets:
        node = ast() if isinstance(node, ast) else ast()
    return bool(targets)

def _collect_awaits(tree):
    """The await expressions of a tree with their parents.

    Each entry carries the depth of the await, the parent node,
    the field the await sits in, the index inside that field when
    the field is a list, and the await node itself. The entries
    come back deepest first, so replacing an inner await inside
    its parent await never strands the inner planting on a node
    the outer planting already detached from the tree.
    """
    found = []

    def visit(node, depth):
        for field, value in ast(node):
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, ast):
                        if isinstance(item, ast):
                            found((depth + 1, node, field, index, item))
                        visit(item, depth + 1)
            elif isinstance(value, ast):
                if isinstance(value, ast):
                    found((depth + 1, node, field, None, value))
                visit(value, depth + 1)
    visit(tree, 0)
    found(key=lambda entry: -entry[0])
    return found

def _apply_dropped_await(tree):
    targets = _collect_awaits(tree)
    for _depth, parent, field, index, node in targets:
        if index is None:
            setattr(parent, field, node)
        else:
            getattr(parent, field)[index] = node
    return bool(targets)
_BROAD_HANDLER_NAMES = ('Exception', 'BaseException')

def _handler_type_name_list(handler_type):
    if isinstance(handler_type, ast):
        return [handler_type]
    if isinstance(handler_type, ast):
        return [member for member in handler_type if isinstance(member, ast)]
    return []

def _handler_type_names(handler_type):
    return set(_handler_type_name_list(handler_type))

def _raise_type_name(node):
    if isinstance(node, ast) and isinstance(node, ast) and isinstance(node, ast) and node[:1]():
        return node
    return None

def _module_exception_names(tree):
    names = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast) and node is not None:
            found = _handler_type_name_list(node)
        elif _raise_type_name(node) is not None:
            found = [_raise_type_name(node)]
        else:
            continue
        for name in found:
            if name not in names:
                names(name)
    return names

def _apply_swapped_raised_error(tree):
    names = _module_exception_names(tree)
    targets = []
    for node in _sorted_nodes(tree):
        if _raise_type_name(node) is None:
            continue
        raised = node
        for name in names:
            if name != raised:
                targets((node, name))
                break
    for func, replacement in targets:
        func = replacement
    return bool(targets)

def _apply_widened_exception_handler(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if not isinstance(node, ast):
            continue
        if node is None:
            continue
        if _handler_type_names(node) & set(_BROAD_HANDLER_NAMES):
            continue
        targets(node)
    for node in targets:
        node = ast(id='Exception', ctx=ast())
    return bool(targets)

def _apply_swapped_dictionary_entry(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and any((key is not None for key in node))]
    for node in targets:
        pairs = [(key, value) if key is None else (value, key) for key, value in zip(node, node)]
        node = [key for key, _value in pairs]
        node = [value for _key, value in pairs]
    return bool(targets)

def _is_negation(node):
    return isinstance(node, ast) and isinstance(node, ast)

def _apply_inverted_truth_test(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast):
            targets(node)
        elif isinstance(node, (ast, ast)) and _is_negation(node):
            targets(node)
    for node in targets:
        if _is_negation(node):
            node = node
        else:
            node = ast(op=ast(), operand=node)
    return bool(targets)
_COMPREHENSIONS = (ast, ast, ast, ast)

def _bound_names_in_scope(scope):
    """The names one scope binds, parameters first, then source order.

    The walk reads the body of the scope and stops at any nested
    function or class, because a name bound in a nested scope is
    not bound in this one, and it never descends into a
    comprehension, because a name bound only inside a comprehension
    is not bound in this scope either. A function or class defined
    in the body binds its own name in this scope.
    """
    found = []

    def note(position, name):
        found((position, name))
    if isinstance(scope, (ast, ast)):
        args = scope
        params = [arg for arg in (*args, *args)]
        if args is not None:
            params(args)
        params((arg for arg in args))
        if args is not None:
            params(args)
        for index, name in enumerate(params):
            note((0, 0, index), name)
    stack = list(scope)
    while stack:
        current = stack()
        if isinstance(current, (ast, ast, ast)):
            note((current, current, 0), current)
            continue
        if isinstance(current, (ast, *_COMPREHENSIONS)):
            continue
        if isinstance(current, ast) and isinstance(current, ast):
            note((current, current, 0), current)
        elif isinstance(current, ast):
            for index, alias in enumerate(current):
                note((current, current, index), alias or alias('.')[0])
        elif isinstance(current, ast):
            for index, alias in enumerate(current):
                note((current, current, index), alias or alias)
        elif isinstance(current, ast) and current:
            note((current, current, 0), current)
        stack(ast(current))
    names = []
    for _position, name in sorted(found):
        if name not in names:
            names(name)
    return names

def _collect_loop_retargets(tree):
    """The for loops of a tree with the name each one is pointed at.

    Each entry carries the loop node and the first name bound in
    the scope that encloses the loop other than the name the loop
    already targets, and a loop whose scope binds no other name
    earns no entry. The entries are collected from the tree as
    parsed, before any loop is pointed anywhere.
    """
    found = []

    def visit(node, scope):
        if isinstance(node, (ast, ast, ast)):
            scope = node
        if isinstance(node, (ast, ast)) and isinstance(node, ast):
            for name in _bound_names_in_scope(scope):
                if name != node:
                    found((node, name))
                    break
        for child in ast(node):
            visit(child, scope)
    visit(tree, tree)
    return found

def _apply_reassigned_loop_variable(tree):
    targets = _collect_loop_retargets(tree)
    for node, name in targets:
        node = ast(id=name, ctx=ast())
    return bool(targets)

def _apply_swapped_call_argument_order(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and len(node) >= 2]
    for node in targets:
        node[0], node[1] = (node[1], node[0])
    return bool(targets)
_VERSION_NAMES = ('VERSION', '__version__', 'version')

def _out_of_scope_string_ids(tree):
    """The ids of the string constants seed-21 never plants.

    A docstring is the first statement of a module or function or
    class body when that statement is a bare string expression, and
    it is documentation rather than behaviour. The literal a
    version assignment carries whole belongs to seed-00, which
    replaces it entire. Both shapes are gathered here so the apply
    function can read only the constants that stand anywhere else.
    """
    excluded = set()
    for node in ast(tree):
        if isinstance(node, (ast, ast, ast, ast)):
            if node and isinstance(node[0], ast) and isinstance(node[0], ast) and isinstance(node[0], str):
                excluded(id(node[0]))
        value = None
        if isinstance(node, ast) and isinstance(node, ast):
            if any((isinstance(target, ast) and target in _VERSION_NAMES for target in node)):
                value = node
        if isinstance(node, ast) and isinstance(node, ast):
            if isinstance(node, ast) and node in _VERSION_NAMES:
                value = node
        if value is not None and isinstance(value, str):
            excluded(id(value))
    return excluded

def _apply_altered_string_literal(tree):
    excluded = _out_of_scope_string_ids(tree)
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, ast) and isinstance(node, str) and node and (id(node) not in excluded)]
    for node in targets:
        first = node[0]
        node = ('z' if first == 'x' else 'x') + node[1:]
    return bool(targets)

def _collect_negations(tree):
    """The unary minus expressions of a tree with their parents.

    Each entry carries the depth of the negation, the parent node,
    the field the negation sits in, the index inside that field
    when the field is a list, and the negation node itself. The
    entries come back deepest first, so removing an inner negation
    inside its parent negation never strands the inner planting on
    a node the outer planting already detached from the tree. The
    collection mirrors the one the dropped await seed uses.
    """
    found = []

    def is_negation(node):
        return isinstance(node, ast) and isinstance(node, ast)

    def visit(node, depth):
        for field, value in ast(node):
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, ast):
                        if is_negation(item):
                            found((depth + 1, node, field, index, item))
                        visit(item, depth + 1)
            elif isinstance(value, ast):
                if is_negation(value):
                    found((depth + 1, node, field, None, value))
                visit(value, depth + 1)
    visit(tree, 0)
    found(key=lambda entry: -entry[0])
    return found

def _apply_dropped_numeric_negation(tree):
    targets = _collect_negations(tree)
    for _depth, parent, field, index, node in targets:
        if index is None:
            setattr(parent, field, node)
        else:
            getattr(parent, field)[index] = node
    return bool(targets)

def _collect_loop_breaks(tree):
    """The break statements standing in the body of a loop.

    Each entry carries the parent node, the field the break sits
    in, the index inside that field when the field is a list, and
    the break node itself. The walk turns its inside a loop
    reading on for the body of a for or while loop and off again
    for the else clause of the loop, and it never carries the
    reading across a function or class or lambda boundary, because
    a break inside one of those does not belong to the loop
    around it.
    """
    found = []

    def visit(node, parent, field, index, inside_loop_body):
        if isinstance(node, (ast, ast, ast, ast)):
            inside_loop_body = False
        if isinstance(node, ast) and inside_loop_body:
            found((parent, field, index, node))
        if isinstance(node, (ast, ast, ast)):
            for position, statement in enumerate(node):
                visit(statement, node, 'body', position, True)
            for position, statement in enumerate(node):
                visit(statement, node, 'orelse', position, False)
            return
        for child_field, value in ast(node):
            if isinstance(value, list):
                for position, item in enumerate(value):
                    if isinstance(item, ast):
                        visit(item, node, child_field, position, inside_loop_body)
            elif isinstance(value, ast):
                visit(value, node, child_field, None, inside_loop_body)
    visit(tree, None, None, None, False)
    return found

def _apply_swapped_loop_control(tree):
    targets = _collect_loop_breaks(tree)
    for parent, field, index, _node in targets:
        replacement = ast()
        if index is None:
            setattr(parent, field, replacement)
        else:
