        node.decorator_list = node.decorator_list[1:]
    return bool(targets)

def _apply_dropped_exception_handler(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, (ast.Try,)) and node.handlers and (len(node.handlers) >= 2 or (node.finalbody and (not node.orelse)))]
