            if any((isinstance(target) and target.id in ('VERSION', '__version__', 'version') for target in node.targets)):
                value = node.value
        if isinstance(node) and isinstance(node.value):
            if isinstance(node.target) and node.target.id in ('VERSION', '__version__', 'version'):
                value = node.value
        if value is not None and isinstance(value.value):
            targets.append(value)
    for value in targets:
        value.value = '9.9.9'
    return bool(targets)

def _apply_dropped_return(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node) and node.value is not None]
    for node in targets:
        node.value = None
    return bool(targets)
_COMPARISON_FLIPS = {ast.Eq: ast.NotEq, ast.NotEq: ast.Eq, ast.Lt: ast.Gt, ast.Gt: ast.Lt, ast.LtE: ast.GtE, ast.GtE: ast.LtE, ast.In: ast.NotIn, ast.NotIn: ast.In, ast.Is: ast.IsNot, ast.IsNot: ast.Is}

def _apply_inverted_comparison(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node) and node.ops:
            flipped = _COMPARISON_FLIPS.get(type(node.ops[0]))
            if flipped is not None:
                targets.append((node, flipped))
    for node, flipped in targets:
        node.ops[0] = flipped()
    return bool(targets)

def _apply_off_by_one(tree):
    targets = []
    seen = set()
    for node in _sorted_nodes(tree):
        if isinstance(node):
            for inner in ast.walk(node):
