        value = None
        if isinstance(node) and isinstance(node.value):
            if any((isinstance(target) and target.id in _VERSION_NAMES for target in node.targets)):
                value = node.value
        if isinstance(node) and isinstance(node.value):
            if isinstance(node.target) and node.target.id in _VERSION_NAMES:
                value = node.value
        if value is not None and isinstance(value.value):
            excluded.add(id(value))
    return excluded

