        if isinstance(node):
            named = [kw for kw in node.keywords if kw.arg is not None]
            if named:
                targets.append((node, named[0]))
    for node, keyword in targets:
        node.keywords.remove(keyword)
    return bool(targets)

def _apply_flipped_range_step(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if not (isinstance(node) and isinstance(node.func) and (node.func.id == 'range') and (len(node.args) == 3)):
            continue
        step = node.args[2]
        if isinstance(step):
            continue
        if isinstance(step) and isinstance(step.op):
            continue
        if isinstance(step) and isinstance(step.value):
            continue
        if _is_zero_literal(step):
            continue
        targets.append(node)
    for node in targets:
        step = node.args[2]
        if _is_int_constant(step):
            node.args[2] = ast.Constant(value=-step.value)
        else:
            node.args[2] = ast.UnaryOp(op=ast.USub(), operand=step)
    return bool(targets)
_TEST_HOLDERS = (ast.If, ast.While, ast.IfExp)

def _collect_outer_negations(tree):
    """The logical negations of a tree standing outside a condition test.

    Each entry carries the depth of the negation, the parent node,
    the field the negation sits in, the index inside that field when
    the field is a list, and the negation node itself. The entries
    come back deepest first, so stripping an inner negation inside
    its parent negation never strands the inner planting on a node
    the outer planting already detached from the tree. A negation
    standing anywhere inside the test expression of an if statement
    or a while loop or a conditional expression is never collected,
    and the exclusion follows the test into everything it carries.
    The guard of a match case is a condition test in the same sense,
    so a negation standing anywhere inside a guard is never
    collected either.
    """
    found = []

    def visit(node, depth, in_test):
        for field, value in ast.iter_fields(node):
            child_in_test = in_test or (field == 'test' and isinstance(node)) or (field == 'guard' and isinstance(node))
            if isinstance(value):
                for index, item in enumerate(value):
                    if isinstance(item):
                        if isinstance(item) and isinstance(item.op) and (not child_in_test):
                            found.append((depth + 1, node, field, index, item))
                        visit(item)
            elif isinstance(value):
                if isinstance(value) and isinstance(value.op) and (not child_in_test):
                    found.append((depth + 1, node, field, None, value))
                visit(value)
    visit(tree)
    found.sort(key=lambda entry: -entry[0])
    return found

def _apply_dropped_logical_negation(tree):
    targets = _collect_outer_negations(tree)
    for _depth, parent, field, index, node in targets:
        if index is None:
            setattr(parent)
        else:
            getattr(parent)[index] = node.operand
    return bool(targets)

@dataclass(frozen=True)
class Seed:
    id: str
    name: str
    defect_class: str
    apply: Callable[[ast.AST], bool]
    description: str = ''
SEEDS = [Seed('seed-00', 'stale version string', 'stale metadata'), Seed('seed-01', 'dropped return value', 'missing result'), Seed('seed-02', 'inverted comparison', 'wrong predicate'), Seed('seed-03', 'off by one constant', 'boundary error'), Seed('seed-04', 'swallowed exception', 'hidden failure'), Seed('seed-05', 'inverted boolean literal', 'wrong flag'), Seed('seed-06', 'swapped arithmetic operator', 'wrong computation'), Seed('seed-07', 'dropped call argument', 'missing input'), Seed('seed-08', 'negated condition', 'wrong branch'), Seed('seed-09', 'removed collection element', 'missing data'), Seed('seed-10', 'range bound shifted by one', 'boundary error'), Seed('seed-11', 'wrong variable returned', 'wrong result'), Seed('seed-12', 'swapped operand order', 'wrong computation'), Seed('seed-13', 'dropped else branch', 'missing fallback'), Seed('seed-14', 'swapped boolean operator', 'wrong predicate'), Seed('seed-15', 'dropped await', 'missing wait'), Seed('seed-16', 'widened exception handler', 'hidden failure'), Seed('seed-17', 'swapped dictionary entry', 'wrong data'), Seed('seed-18', 'inverted truth test', 'wrong branch'), Seed('seed-19', 'reassigned loop variable', 'wrong variable'), Seed('seed-20', 'swapped call argument order', 'wrong input'), Seed('seed-21', 'altered string literal', 'wrong text'), Seed('seed-22', 'dropped numeric negation', 'wrong sign'), Seed('seed-23', 'swapped loop control', 'wrong flow'), Seed('seed-24', 'swapped augmented assignment operator', 'wrong computation'), Seed('seed-25', 'identity test replaced by equality', 'wrong predicate'), Seed('seed-26', 'subscript index shifted by one', 'boundary error'), Seed('seed-27', 'swapped keyword argument values', 'wrong input'), Seed('seed-28', 'swapped raised error', 'wrong error'), Seed('seed-29', 'slice stop shifted by one', 'boundary error'), Seed('seed-30', 'shifted numeric default', 'wrong default'), Seed('seed-31', 'swapped sibling attribute', 'wrong attribute'), Seed('seed-32', 'narr