            node.finalbody = []
        else:
            node.finalbody = [ast.Pass()]
    return bool(targets)

def _apply_dropped_decorator(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, (ast.AsyncFunctionDef, ast.ClassDef)) and node.decorator_list]
    for node in targets:
        node.decorator_list = node.decorator_list[1:]
    return bool(targets)

def _apply_dropped_exception_handler(tree):
    targets = [node for node in _sorted_nodes(tree) if isinstance(node, (ast.TryStar,)) and node.handlers and (len(node.handlers) >= 2 or (node.finalbody and (not node.orelse)))]
    for node in targets:
