ed_augmented_operator, 'Swaps the operator of an augmented assignment so the value it accumulates moves the wrong way'), Seed('seed-25', 'identity test replaced by equality', 'wrong predicate', _apply_identity_comparison_as_equality, 'Replaces an identity comparison with an equality comparison so the test asks sameness of value instead of sameness of object'), Seed('seed-26', 'subscript index shifted by one', 'boundary error', _apply_subscript_index_shift, 'Raises the constant index of a subscript by one so the code reads the element beside the one it named'), Seed('seed-27', 'swapped keyword argument values', 'wrong input', _apply_swapped_keyword_argument_values, 'Swaps the values of the first two keyword arguments of a call so each value binds to the wrong parameter'), Seed('seed-28', 'swapped raised error', 'wrong error', _apply_swapped_raised_error, 'Swaps the exception type a raise throws for the first other exception type the module names so the error a caller handles is never the one that arrives'), Seed('seed-29', 'slice stop shifted by one', 'boundary error', _apply_slice_stop_shift, 'Raises the stop of a slice by one so the code takes one element more than the slice it wrote'), Seed('seed-30', 'shifted numeric default', 'wrong default', _apply_shifted_numeric_default, 'Raises a numeric argument default by one so a call that leaves the argument out runs with a value the code never wrote'), Seed('seed-31', 'swapped sibling attribute', 'wrong attribute', _apply_swapped_sibling_attribute, 'Reads the second attribute a scope loads off one object in place of the first so the value comes from a different part of the object than the code named'), Seed('seed-32', 'narrowed exception handler', 'exposed failure', _apply_narrowed_exception_handler, 'Narrows an exception handler that names the broad base error type to the first specific error type its try body raises so the other failures the handler was written to recover from escape past it'), Seed('seed-33', 'swapped parameter defaults', 'wrong default', _apply_swapped_parameter_defaults, 'Exchanges the first two argument defaults of a definition so each parameter falls back to the value the code wrote for the other'), Seed('seed-34', 'dropped finally body', 'missing cleanup', _apply_dropped_finally_body, 'Drops the finally block of a try statement so the cleanup the code wrote to run on every path never runs'), Seed('seed-35', 'dropped decorator', 'missing wrapper', _apply_dropped_decorator, 'Removes the first decorator from a definition so the behaviour the decorator added never runs'), Seed('seed-36', 'dropped exception handler', 'missing recovery', _apply_dropped_exception_handler, 'Removes the first exception handler of a try statement so the failure it was written to recover from reaches a later handler instead, or escapes to the caller where no handler stands after it'), Seed('seed-37', 'dropped yield', 'missing production', _apply_dropped_yield, 'Replaces each yield with the value it yields so the function runs as an ordinary function and produces none of the items it was written to generate'), Seed('seed-38', 'dropped condition term', 'wrong predicate', _apply_dropped_condition_term, 'Drops the last term of a compound condition so the cases that term admitted or rejected are decided by the terms that stay'), Seed('seed-39', 'dropped base class', 'missing inheritance', _apply_dropped_base_class, 'Removes the first base class of a class definition so the behaviour the class inherited from that base is not there'), Seed('seed-40', 'shifted slice start', 'boundary error', _apply_slice_start_shift, 'Raises the start of a slice by one so the code takes its elements from one position later than the slice it wrote'), Seed('seed-41', 'reversed loop control', 'wrong flow', _apply_reversed_loop_control, 'Turns a continue inside a loop into a break so the loop ends at the first item it was written to skip and every later item goes unprocessed'), Seed('seed-42', 'dropped scope declaration', 'wrong scope', _apply_dropped_scope_declaration, 'Removes a global or nonlocal declaration so a plain assignment meant for the module or the enclosing scope lands in a local and is lost silently, and an augmented assignment reads that local first and raises instead'), Seed('seed-43', 'swapped assignment values', 'wrong data', _apply_swapped_assignment_values, 'Exchanges the first two elements of the tuple an assignment binds so each name takes the value the code wrote for the other'), Seed('seed-44', 'dropped loop else clause', 'missing fallback', _apply_dropped_loop_else, 'Drops the else clause of a loop so the code written to run when the loop finishes without a break never runs'), Seed('seed-45', 'dropped keyword argument', 'missing input', _apply_dropped_keyword_argument, 'Drops the first keyword argument of a call so the callee never receives the value the caller named for that parameter'), Seed('seed-46', 'flipped range step sign', 'wrong direction', _apply_flipped_range_step, 'Negates the step of a range call carrying three arguments so the sequence travels in the opposite direction from the one the code wrote'), Seed('seed-47', 'dropped logical negation', 'wrong flag', _apply_dropped_logical_negation, 'Removes a logical not standing outside a condition test so the expression it negated carries the opposite truth from the one the code wrote')]
