    assert alpha_value() == 10
    assert alpha_scale(3) == 6


def test_beta():
    assert beta_value() == 20
    assert beta_scale(4) == 12
'
TINY_SOURCE = 'def answer():
    return 42
'
TINY_TEST_SOURCE = 'from tiny import answer


def test_answer():
    assert answer() == 42
'
